    [[say('皮膚', 'Skin'), ks > .05 ? say('蕁麻疹', 'urticaria') : '—'], [say('呼吸道', 'Airway'), kc > .6 ? say('聲音沙啞、喘鳴', 'hoarse, stridor') : '—'], [say('呼吸', 'Breathing'), kc > .3 ? say('喘鳴音', 'wheeze') : '—'], [say('循環', 'Circulation'), sbp < 90 ? say('低血壓', 'hypotension') : '—']].forEach((r, i) => { txt(g, r[0], 262, 384 + i * 15, { s: 11, mono: true, c: '#9fe' }); txt(g, r[1], 360, 384 + i * 15, { s: 11.5, c: r[1] === '—' ? '#9ab' : '#ffb3b3' }); });
    const L = s.L; L(150, 400, ks > .05 ? '蕁麻疹、唇部腫脹' : '皮膚正常', ks > .05 ? 'Urticaria, lip swelling' : 'Skin clear', 300, 340, ks > .05 ? C.a : C.n);
    if (adr) L(530, 140, '腎上腺素後血壓回升、心跳下降', 'BP recovers, HR settles after adrenaline', 300, 316, C.t); else if (ah) L(530, 140, '抗組織胺只改善皮膚，不治療休克', 'Antihistamine helps skin only — not shock', 300, 316, C.w); else L(200, 214, kc > .6 ? '脈波振幅變小（血管擴張、低血壓）' : '血氧脈波', kc > .6 ? 'Small pleth (vasodilatation, hypotension)' : 'Pulse oximetry waveform', 300, 316, kc > .6 ? C.a : C.n);
