  const RA_RX = {
    thrombectomy: { zh: '動脈內取栓術', en: 'Endovascular thrombectomy', text: '導管經股或橈動脈送到阻塞的大血管，以支架取栓器或抽吸導管把血栓拉出，血管再通（mTICI 2b–3）。只有尚未梗塞的缺血半影區能被救回；CT 上已明顯低密度的核心不會恢復，所以「時間就是腦」。', textEn: 'A catheter from the femoral or radial artery reaches the occluded large vessel and a stent retriever or aspiration catheter pulls the clot out (mTICI 2b–3 reperfusion). Only the penumbra that has not yet infarcted is saved; a core that is already hypodense on CT does not recover — time is brain.' },
    anticoag: { zh: '抗凝血治療', en: 'Anticoagulation', text: '抗凝血阻止血栓繼續延伸與新的栓子形成，由身體自己的纖溶系統在數週到數月內溶解血栓；所以今天的 CT 影像不會改變，是療效需要時間的例子。', textEn: 'Anticoagulation stops the clot propagating and new emboli forming while the body\'s own fibrinolysis dissolves the thrombus over weeks to months — so today\'s CT does not change; the benefit takes time.' },
    lysis: { zh: '全身血栓溶解（高風險肺栓塞）', en: 'Systemic thrombolysis (high-risk PE)', text: '肺栓塞合併休克或持續低血壓時，靜脈給予血栓溶解劑可在數小時內縮小血栓、降低右心負荷；出血風險高，禁忌症須逐一確認，部分病人改用導管導引治療。', textEn: 'In pulmonary embolism with shock or sustained hypotension, intravenous thrombolysis shrinks the clot within hours and unloads the right ventricle; bleeding risk is high, contraindications must be checked, and some patients receive catheter-directed treatment instead.' },
    adrenaline: { zh: '肌肉注射腎上腺素', en: 'Intramuscular adrenaline', text: '過敏性休克的第一線治療：α 作用收縮血管、提升血壓並減輕喉頭水腫，β 作用擴張支氣管並抑制肥大細胞釋放介質。同時停止顯影劑、給氧、平躺抬腿並快速輸液；必要時重複並請求支援。', textEn: 'First-line treatment for anaphylaxis: alpha effects constrict vessels, raise blood pressure and reduce laryngeal oedema, beta effects dilate the bronchi and stabilise mast cells. At the same time stop the contrast, give oxygen, lay the patient flat with legs raised and give rapid fluids; repeat and call for help as needed.' },
    antihist: { zh: '抗組織胺', en: 'Antihistamine', text: '只能緩解蕁麻疹與搔癢，屬於輔助治療；它不會提升血壓、也不能打開呼吸道，絕不可取代腎上腺素。影像上皮膚紅疹減少，但生命徵象不變。', textEn: 'Relieves urticaria and itch only — an adjunct; it does not raise blood pressure or open the airway and must never replace adrenaline. The skin clears but the vital signs do not change.' },
    embolise: { zh: '經導管栓塞（線圈）', en: 'Transcatheter coil embolisation', text: '微導管超選擇性進入出血分支，放置線圈或栓塞劑使血管內血栓化，外滲立即停止；脾臟外傷常用近端或遠端栓塞以保留脾臟功能。', textEn: 'A microcatheter is placed super-selectively in the bleeding branch and coils or embolic agent thrombose it, stopping extravasation at once; in splenic trauma proximal or distal embolisation preserves splenic function.' }
  };
  dep('radiology', '放射科', 'Radiology', RA_RX, [
    { id: 'acute-stroke', zh: '急性缺血性腦中風（MCA）', en: 'Acute ischaemic stroke (MCA)', rx: ['thrombectomy'], views: [
      { id: 'ct', zh: '非顯影 CT（中風窗）', en: 'Non-contrast CT (stroke window)', mod: 'CT', hdr: 'CT HEAD NON-CONTRAST · W40/L40', p: P('發病後時間', 'Time since onset', 0, 6, 3, ' h', { step: .25, normal: 0 }), draw: strokeCT, h: s => ({ lr: 'R', lrx: 14, lry: 112, note: 'ASPECTS ' + aspects(s) + '/10' }) },
      { id: 'dsa', zh: '腦血管攝影', en: 'Cerebral angiogram', mod: 'DSA', hdr: 'LEFT ICA INJECTION · AP', p: sev('側枝循環不足', 'Collateral failure'), draw: neuroDSA, h: s => ({ lr: 'R', lrx: 20, note: s.normal || s.has('thrombectomy') ? 'mTICI 3' : 'mTICI 0 · M1 occlusion' }) }],
      f: '急性大腦中動脈阻塞時，非顯影 CT 最早看到的是血栓本身：血管呈高密度（高密度 MCA 徵，或側裂內的「點徵」）。數小時內缺血區灰白質分界消失，島葉皮質帶與豆狀核輪廓模糊、腦溝變淺。ASPECTS 把 MCA 供血區分成 10 區（C、L、IC、I、M1–M6），每個受影響區扣 1 分；≥6 分是取栓的傳統門檻，近年研究也顯示部分較大核心仍可獲益。血管攝影確認 M1 截斷，側枝循環好的人核心長得慢。', fEn: 'In acute middle cerebral artery occlusion the earliest non-contrast CT sign is the thrombus itself, a hyperdense vessel (the hyperdense MCA sign, or a "dot" in the Sylvian fissure). Within hours the ischaemic territory loses grey–white differentiation: the insular ribbon and lentiform nucleus blur and the sulci efface. ASPECTS divides the MCA territory into 10 regions (C, L, IC, I, M1–M6) and subtracts a point for each involved region; 6 or more is the classic threshold for thrombectomy, and recent trials show benefit for some larger cores. Angiography confirms the M1 cut-off, and patients with good collaterals grow their core more slowly.' },
    { id: 'pe', zh: '肺栓塞（CTPA）', en: 'Pulmonary embolism (CTPA)', rx: ['anticoag', 'lysis'], views: [{ id: 'ctpa', zh: 'CT 肺動脈血管攝影', en: 'CT pulmonary angiogram', mod: 'CT', hdr: 'CTPA AXIAL · MEDIASTINAL WINDOW', p: sev('血栓負荷', 'Clot burden'), draw: ctpa, h: s => ({ lr: 'R', lrx: 20, note: say('阻塞指數 ', 'Obstruction index ') + Math.round((s.normal ? 0 : s.k * (s.has('lysis') ? .22 : 1)) * 100) + '%' }) }],
      f: 'CT 肺動脈血管攝影時顯影劑把肺動脈照亮，血栓則是腔內的低密度充盈缺損：橫切面像「薄荷糖」，沿血管走向像「鐵軌」，騎跨在分叉處者稱鞍狀栓塞。血栓負荷越大，右心室越擴張；右心室／左心室直徑比大於 1 代表右心負荷，與血壓、肌鈣蛋白一起做風險分層。', fEn: 'On CT pulmonary angiography the opacified arteries are bright and thrombus is an intraluminal filling defect — a "polo mint" in cross-section, "railway tracks" along the vessel, and a saddle embolus when it straddles the bifurcation. The larger the clot burden, the more the right ventricle dilates; an RV/LV diameter ratio above 1 indicates right-heart strain and, with blood pressure and troponin, drives risk stratification.' },
    { id: 'contrast-reaction', zh: '顯影劑過敏反應', en: 'Contrast reaction', rx: ['adrenaline', 'antihist'], views: [{ id: 'mon', zh: '生命徵象監視器', en: 'Vital-signs monitor', mod: 'MON', hdr: 'CT SUITE · PATIENT MONITOR', p: sev('反應嚴重度', 'Reaction severity'), draw: contrastMon, anim: true }],
      f: '碘顯影劑急性反應多在注射後 20 分鐘內發生：輕度只有蕁麻疹與搔癢，中度出現支氣管痙攣、喘鳴或臉部水腫。重度即過敏性休克——血壓下降、心搏過速、喉頭水腫與血氧下降。處置是停止注射、呼救並評估呼吸道、呼吸與循環；只要呼吸道或循環受影響，肌肉注射腎上腺素就是第一線治療。', fEn: 'Acute iodinated-contrast reactions usually begin within 20 minutes of injection: mild reactions are urticaria and itch, moderate reactions add bronchospasm, wheeze or facial oedema. Severe reactions are anaphylaxis — hypotension, tachycardia, laryngeal oedema and falling saturation. Stop the injection, call for help and assess airway, breathing and circulation; whenever airway or circulation is involved, intramuscular adrenaline is first-line treatment.' },
    { id: 'active-bleed', zh: '活動性出血（介入血管攝影）', en: 'Active bleeding (interventional angiography)', rx: ['embolise'], views: [{ id: 'dsa', zh: '腹腔動脈血管攝影', en: 'Coeliac angiogram', mod: 'DSA', hdr: 'COELIAC DSA · ARTERIAL PHASE', p: sev('出血速率', 'Bleeding rate'), draw: bleedDSA, h: { lr: 'R', lrx: 20 } }],
      f: '數位減影血管攝影把骨頭與軟組織減去，只留下顯影劑：正常動脈呈樹枝狀、管徑逐漸變細。活動性出血是顯影劑跑出血管外形成的不規則「雲霧」，在後期影像擴大、積聚而不隨靜脈相排空。同一次檢查即可把微導管送到出血分支，以線圈或栓塞劑止血，常能免除開腹手術。', fEn: 'Digital subtraction angiography removes bone and soft tissue so only contrast remains: normal arteries branch and taper smoothly. Active bleeding is contrast leaving the vessel as an irregular blush that grows and pools on later frames instead of washing out with the venous phase. In the same sitting a microcatheter can be steered into the bleeding branch and the leak sealed with coils or embolic agent, often avoiding laparotomy.' }
  ]);

