  const DE_RX = {
    excision: { zh: '手術切除', en: 'Surgical excision', text: '懷疑黑色素瘤時以 1–3 mm 邊界完整切除送病理，再依 Breslow 厚度決定擴大切除範圍與是否做前哨淋巴結切片；基底細胞癌以數毫米邊界切除或莫氏顯微手術。病灶變成一條順著皮紋的線狀縫合傷口。', textEn: 'A suspected melanoma is excised completely with a 1–3 mm margin for histology, and Breslow thickness then decides the wider re-excision margin and sentinel node biopsy; basal cell carcinoma is excised with a margin of a few millimetres or by Mohs micrographic surgery. The lesion becomes a linear sutured scar along the skin-tension lines.' },
    topical: { zh: '外用免疫調節劑', en: 'Topical immune modifier', text: '淺層型基底細胞癌可外用 imiquimod 數週，誘發局部免疫清除腫瘤，過程中會紅腫結痂；結節型或臉部高風險部位不適用，仍以手術為主。', textEn: 'Superficial basal cell carcinoma can be treated with topical imiquimod for several weeks, triggering local immune clearance with redness and crusting along the way; it is not suitable for nodular tumours or high-risk facial sites, where surgery remains standard.' },
    cryo: { zh: '冷凍治療', en: 'Cryotherapy', text: '液態氮使角化細胞壞死，病灶在 1–2 週內結痂脫落，可能留下淡色斑；診斷不確定時應先切片而非冷凍。', textEn: 'Liquid nitrogen destroys the keratinocytes and the lesion crusts and falls off within 1–2 weeks, sometimes leaving a pale patch; if the diagnosis is uncertain, biopsy rather than freeze.' },
    reassure: { zh: '衛教、觀察', en: 'Reassurance', text: '典型脂漏性角化症是良性的，不需要治療；皮膚鏡確認特徵後說明即可，影像不會改變。若短時間內大量出現需想到內臟惡性腫瘤（Leser–Trélat 徵）。', textEn: 'A typical seborrhoeic keratosis is benign and needs no treatment; once dermoscopy confirms the features, explanation is enough and the image does not change. A sudden eruption of many lesions raises the question of internal malignancy (Leser–Trélat sign).' },
    'topical-ps': { zh: '外用維生素 D 類似物＋類固醇', en: 'Topical vitamin D analogue + steroid', text: '外用藥抑制角質細胞過度增生與發炎，數週內斑塊變薄、鱗屑減少，適合輕度乾癬；頭皮與皺褶處需選擇合適劑型。', textEn: 'Topical therapy curbs keratinocyte over-proliferation and inflammation, so plaques thin and scale lessens within weeks; it suits mild psoriasis, with suitable formulations for scalp and folds.' },
    photo: { zh: '窄波 UVB 照光', en: 'Narrowband UVB phototherapy', text: '每週 2–3 次 311 nm 窄波 UVB：乾癬中抑制皮膚內的免疫細胞，2–3 個月內斑塊變淡；白斑中刺激毛囊內的黑色素細胞儲備，從毛孔周圍長出點狀色素島。', textEn: 'Narrowband 311 nm UVB two to three times a week: in psoriasis it suppresses the immune infiltrate and plaques fade over 2–3 months; in vitiligo it activates the melanocyte reservoir in hair follicles so pigment islands appear around the pores.' },
    biologic: { zh: '生物製劑（IL-17／IL-23 阻斷）', en: 'Biologic (IL-17 / IL-23 blockade)', text: '中重度乾癬以阻斷 IL-17 或 IL-23 的單株抗體治療，多數病人 3–4 個月達到 PASI 90，也改善乾癬性關節炎；開始前需篩檢結核與 B 型肝炎。', textEn: 'Moderate to severe psoriasis is treated with monoclonal antibodies blocking IL-17 or IL-23; most patients reach PASI 90 within 3–4 months and psoriatic arthritis improves too. Tuberculosis and hepatitis B are screened for first.' },
    'emollient-tcs': { zh: '保濕＋外用類固醇', en: 'Emollients + topical steroid', text: '每天大量保濕修補皮膚屏障，急性發作時外用類固醇（臉部與皺褶可用鈣調磷酸酶抑制劑）控制發炎；紅斑與抓痕數週內改善，緩解後改為每週數次的維持治療。', textEn: 'Generous daily emollients repair the barrier and a topical steroid (or a calcineurin inhibitor on face and folds) controls flares; erythema and excoriations settle within weeks, followed by twice-weekly maintenance.' },
    'biologic-ad': { zh: '生物製劑（IL-4／IL-13 阻斷）', en: 'Biologic (IL-4 / IL-13 blockade)', text: '外用藥控制不佳的中重度異位性皮膚炎，可用阻斷 IL-4／IL-13 訊號的單株抗體（如 dupilumab）抑制第二型發炎，搔癢與 EASI 在數週到數月內明顯下降；可能出現結膜炎。', textEn: 'Moderate to severe atopic dermatitis not controlled topically can be treated with a monoclonal antibody blocking IL-4/IL-13 signalling (such as dupilumab), damping type-2 inflammation so itch and EASI fall substantially over weeks to months; conjunctivitis can occur.' },
    tci: { zh: '外用鈣調磷酸酶抑制劑／類固醇', en: 'Topical calcineurin inhibitor / steroid', text: '外用藥抑制攻擊黑色素細胞的 T 細胞，穩定病灶並從邊緣慢慢復色；臉部與頸部效果最好，手腳末端反應差。', textEn: 'Topical therapy suppresses the T cells attacking melanocytes, stabilising patches and repigmenting slowly from the edge; it works best on the face and neck and poorly on hands and feet.' }
  };
  const dermV = (draw, p) => ({ id: 'derm', zh: '皮膚鏡', en: 'Dermoscopy', mod: 'DERM', hdr: 'POLARISED DERMOSCOPY · ×10', p, draw });
  dep('dermatology', '皮膚科', 'Dermatology', DE_RX, [
    { id: 'melanoma', zh: '黑色素瘤 vs 良性痣', en: 'Melanoma vs benign naevus', rx: ['excision'], views: [Object.assign(dermV(melanoma, sev('非典型程度（ABCD）', 'Atypia (ABCD)')), { h: s => { const t = tds(s.normal ? 0 : s.k); return { note: s.has('excision') ? '' : 'TDS ' + t.t.toFixed(2) + ' (A' + t.A + ' B' + t.B + ' C' + t.C + ' D' + t.D + ')' + (t.t > 5.45 ? say(' · 疑黑色素瘤', ' · suspicious') : t.t >= 4.75 ? say(' · 可疑', ' · borderline') : say(' · 良性', ' · benign')) }; } })],
      f: '皮膚鏡以 ABCD 規則評估色素病灶：不對稱（A）、邊界突然中斷（B）、顏色種類（C：淺褐、深褐、黑、藍灰、紅、白）與皮膚鏡結構種類（D）。良性痣對稱、色素網規則並向周邊淡出；黑色素瘤出現不規則網、周邊不規則黑點、偽足狀放射紋、藍白幕與退化構造。總皮膚鏡分數（TDS）大於 5.45 高度懷疑黑色素瘤，應切除送病理。', fEn: 'Dermoscopy scores pigmented lesions with the ABCD rule: asymmetry (A), abrupt border cut-off (B), number of colours (C — light and dark brown, black, blue-grey, red, white) and number of dermoscopic structures (D). A benign naevus is symmetric with a regular network that fades at the periphery; melanoma shows an atypical network, irregular peripheral black dots, pseudopod streaks, a blue-white veil and regression structures. A total dermoscopy score above 5.45 is highly suggestive of melanoma and the lesion is excised for histology.' },
    { id: 'bcc', zh: '基底細胞癌', en: 'Basal cell carcinoma', rx: ['excision', 'topical'], views: [dermV(bcc, sev('腫瘤大小／分期', 'Tumour size / stage'))],
      f: '基底細胞癌是最常見的皮膚癌，好發於曬到太陽的臉部。皮膚鏡特徵是粉紅、珍珠般半透明背景上清晰的樹枝狀血管，加上藍灰色卵圓巢與亮白色構造，晚期中央潰瘍。很少轉移但會局部侵犯；結節型以手術（含莫氏手術）切除，淺層型可用外用免疫調節劑或光動力治療。', fEn: 'Basal cell carcinoma is the commonest skin cancer, usually on sun-exposed facial skin. Dermoscopy shows sharply focused arborising vessels on a pink, pearly translucent background with blue-grey ovoid nests and shiny white structures, and central ulceration later. It rarely metastasises but invades locally; nodular tumours are excised (including Mohs surgery) and superficial ones can be treated with a topical immune modifier or photodynamic therapy.' },
    { id: 'seb-k', zh: '脂漏性角化症', en: 'Seborrhoeic keratosis', rx: ['cryo', 'reassure'], views: [dermV(seborrhoeicK, sev('厚度／色素', 'Thickness / pigment'))],
      f: '脂漏性角化症是良性的表皮增生，看起來像「黏上去」的褐色斑塊，邊界清楚、呈蟲蛀狀。皮膚鏡特徵包括腦迴狀溝回、粟粒狀囊腫（白黃色小點）與粉刺樣開口（深色小坑），藉此與黑色素瘤區分。不需治療；在意外觀或受刺激時可冷凍治療。', fEn: 'Seborrhoeic keratosis is a benign epidermal growth that looks "stuck on": a sharply demarcated brown plaque with a moth-eaten edge. Dermoscopy shows a brain-like pattern of ridges and fissures, milia-like cysts (white-yellow dots) and comedo-like openings (dark craters), which separate it from melanoma. No treatment is needed; cryotherapy is used for cosmetic or irritated lesions.' },
    { id: 'psoriasis', zh: '尋常性乾癬', en: 'Plaque psoriasis', rx: ['topical-ps', 'photo', 'biologic'], views: [{ id: 'map', zh: '身體分布圖', en: 'Body map', mod: 'MAP', hdr: 'PSORIASIS · DISTRIBUTION + CLOSE-UP', p: P('PASI', 'PASI', 0, 50, 18, '', { normal: 0 }), draw: (g, s) => bodyMap(g, s, 'pso') }],
      f: '尋常性乾癬是 Th17 驅動的慢性發炎：界線清楚的鮭魚紅斑塊覆蓋銀白色鱗屑，好發於手肘與膝蓋伸側、頭皮、腰薦部與肚臍，刮除鱗屑可見點狀出血（Auspitz 徵）。PASI 依各區面積與紅、厚、屑評分（0–72）；約三成病人合併乾癬性關節炎。輕度用外用藥，中重度用照光或生物製劑，目標 PASI 90。', fEn: 'Plaque psoriasis is chronic Th17-driven inflammation: sharply demarcated salmon-red plaques with silvery scale over the extensor elbows and knees, scalp, lumbosacral area and umbilicus; removing the scale leaves pinpoint bleeding (Auspitz sign). PASI scores area, redness, thickness and scale by region (0–72), and about a third of patients develop psoriatic arthritis. Mild disease is treated topically, moderate to severe disease with phototherapy or biologics, aiming for PASI 90.' },
    { id: 'atopic-dermatitis', zh: '異位性皮膚炎', en: 'Atopic dermatitis', rx: ['emollient-tcs', 'biologic-ad'], views: [{ id: 'map', zh: '身體分布圖', en: 'Body map', mod: 'MAP', hdr: 'ATOPIC DERMATITIS · DISTRIBUTION + CLOSE-UP', p: P('EASI', 'EASI', 0, 72, 24, '', { normal: 0 }), draw: (g, s) => bodyMap(g, s, 'ecz') }],
      f: '異位性皮膚炎是皮膚屏障缺損加上第二型（Th2）發炎：較大兒童與成人好發於肘窩、膕窩、頸部與手腕等屈側，呈界線不清的紅斑、丘疹與滲液，搔抓留下抓痕，久了皮膚增厚成苔蘚化。EASI 評估面積與嚴重度（0–72）；保濕與外用類固醇是基礎，中重度可用阻斷 IL-4／IL-13 的生物製劑。', fEn: 'Atopic dermatitis is a defective skin barrier plus type-2 (Th2) inflammation: in older children and adults it favours the flexures — antecubital and popliteal fossae, neck and wrists — with ill-defined erythema, papules and weeping, scratch marks (excoriations) and, over time, thickened lichenified skin. EASI scores extent and severity (0–72); emollients and topical steroids are the foundation, and moderate to severe disease can be treated with a biologic blocking IL-4/IL-13.' },
    { id: 'vitiligo', zh: '白斑（伍氏燈）', en: "Vitiligo (Wood's lamp)", rx: ['photo', 'tci'], views: [
      { id: 'woods', zh: '伍氏燈', en: "Wood's lamp", mod: 'WOOD', hdr: 'TRUNK · UVA 365 nm', p: P('脫色面積', 'Depigmented area', 1, 30, 10, '% BSA', { normal: 0 }), draw: (g, s) => vitiligo(g, s, true) },
      { id: 'clinical', zh: '一般光線', en: 'Visible light', mod: 'MAP', hdr: 'TRUNK · CLINICAL VIEW', p: P('脫色面積', 'Depigmented area', 1, 30, 10, '% BSA', { normal: 0 }), draw: (g, s) => vitiligo(g, s, false) }],
      f: '白斑是自體免疫破壞黑色素細胞，形成界線清楚、乳白色的脫色斑，常對稱分布於口周、手背、肚臍周圍與皺褶處。伍氏燈（365 nm 紫外光）下完全脫色區發出亮藍白色螢光、邊界更清楚，能找出日光下看不見的早期病灶，並與只是色素變淡的疾病區分。窄波 UVB 照光後從毛囊周圍長出點狀色素島。', fEn: 'Vitiligo is autoimmune destruction of melanocytes, producing sharply demarcated milk-white depigmented patches, often symmetrical around the mouth, backs of the hands, umbilicus and skin folds. Under a Wood\'s lamp (365 nm ultraviolet) completely depigmented skin fluoresces bright blue-white with a sharper edge, revealing early patches invisible in daylight and separating it from conditions with only partial pigment loss. After narrowband UVB, pigment islands return around the hair follicles.' }
  ]);

